// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// BeginTransfer API-12 begin a scoped artifact transfer
	// (POST /artifacts/transfers)
	BeginTransfer(ctx context.Context, request BeginTransferRequestObject) (BeginTransferResponseObject, error)
	// FinalizeTransfer API-12 finalize after verifying actual bytes, size, hash and object version
	// (POST /artifacts/{handle}/finalizations)
	FinalizeTransfer(ctx context.Context, request FinalizeTransferRequestObject) (FinalizeTransferResponseObject, error)
	// Search API-08 cited context under current authorization
	// (POST /knowledge/searches)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// CreateSnapshot API-08 freeze exact source revisions for retrieval (P2.6)
	// (POST /knowledge/snapshots)
	CreateSnapshot(ctx context.Context, request CreateSnapshotRequestObject) (CreateSnapshotResponseObject, error)
	// GetSnapshot API-08 read a snapshot (P2.6)
	// (GET /knowledge/snapshots/{snapshotId})
	GetSnapshot(ctx context.Context, request GetSnapshotRequestObject) (GetSnapshotResponseObject, error)
	// ListSources API-07 the sources the caller may read, with ACL revision and ingest state
	// (GET /knowledge/sources)
	ListSources(ctx context.Context, request ListSourcesRequestObject) (ListSourcesResponseObject, error)
	// RegisterSource API-07 register an approved source reference for ingestion
	// (POST /knowledge/sources)
	RegisterSource(ctx context.Context, request RegisterSourceRequestObject) (RegisterSourceResponseObject, error)
	// BeginSourceUpload API-08 a single-use upload capability for one document (P2.6)
	// (POST /knowledge/sources/uploads)
	BeginSourceUpload(ctx context.Context, request BeginSourceUploadRequestObject) (BeginSourceUploadResponseObject, error)
	// DeleteSource API-14 block readability now; projections are cleared asynchronously
	// (DELETE /knowledge/sources/{sourceId})
	DeleteSource(ctx context.Context, request DeleteSourceRequestObject) (DeleteSourceResponseObject, error)
	// GetSource Read a source with its current ACL revision and ingest state
	// (GET /knowledge/sources/{sourceId})
	GetSource(ctx context.Context, request GetSourceRequestObject) (GetSourceResponseObject, error)
	// ReplaceSourceAccess API-13 replace the trusted ACL under an expected ACL revision
	// (PUT /knowledge/sources/{sourceId}/access)
	ReplaceSourceAccess(ctx context.Context, request ReplaceSourceAccessRequestObject) (ReplaceSourceAccessResponseObject, error)
	// CreateToolCall API-11 create a tracked tool call
	// (POST /mcp/calls)
	CreateToolCall(ctx context.Context, request CreateToolCallRequestObject) (CreateToolCallResponseObject, error)
	// GetToolCall API-11 query the original call outcome
	// (GET /mcp/calls/{callId})
	GetToolCall(ctx context.Context, request GetToolCallRequestObject) (GetToolCallResponseObject, error)
	// ReconcileToolCall API-11 operator reconciliation of one call (P1.2, P2.5)
	// (POST /mcp/calls/{callId}/reconciliations)
	ReconcileToolCall(ctx context.Context, request ReconcileToolCallRequestObject) (ReconcileToolCallResponseObject, error)
	// ListCatalog API-10 visible reviewed catalog; visibility is not a grant
	// (GET /mcp/catalog)
	ListCatalog(ctx context.Context, request ListCatalogRequestObject) (ListCatalogResponseObject, error)
	// DiscoverServer API-15 record the live descriptor of a server as a revision awaiting review
	// (POST /mcp/catalog/discoveries)
	DiscoverServer(ctx context.Context, request DiscoverServerRequestObject) (DiscoverServerResponseObject, error)
	// ReviewDescriptor API-15 authorized review decision bound to the exact descriptor digest
	// (POST /mcp/catalog/{serverId}/reviews)
	ReviewDescriptor(ctx context.Context, request ReviewDescriptorRequestObject) (ReviewDescriptorResponseObject, error)
	// ListGrants API-16 grants the caller may see
	// (GET /mcp/grants)
	ListGrants(ctx context.Context, request ListGrantsRequestObject) (ListGrantsResponseObject, error)
	// CreateGrant API-10 create a grant bound to a descriptor revision and method scope
	// (POST /mcp/grants)
	CreateGrant(ctx context.Context, request CreateGrantRequestObject) (CreateGrantResponseObject, error)
	// GetGrant Read a grant and its revocation progress
	// (GET /mcp/grants/{grantId})
	GetGrant(ctx context.Context, request GetGrantRequestObject) (GetGrantResponseObject, error)
	// GetRevocationProgress API-16 blocked new admission versus converged senders of a grant's revocation
	// (GET /mcp/grants/{grantId}/revocation)
	GetRevocationProgress(ctx context.Context, request GetRevocationProgressRequestObject) (GetRevocationProgressResponseObject, error)
	// RevokeGrant API-16 revoke; new admission is blocked immediately, convergence is tracked
	// (POST /mcp/grants/{grantId}/revocations)
	RevokeGrant(ctx context.Context, request RevokeGrantRequestObject) (RevokeGrantResponseObject, error)
	// ListMemories API-09 memory facts the caller may see, by subject and state
	// (GET /memories)
	ListMemories(ctx context.Context, request ListMemoriesRequestObject) (ListMemoriesResponseObject, error)
	// ProposeMemory API-09 propose a memory fact; models never confirm
	// (POST /memories)
	ProposeMemory(ctx context.Context, request ProposeMemoryRequestObject) (ProposeMemoryResponseObject, error)
	// RecallMemories API-09 recall confirmed facts under current authorization (P2.6)
	// (POST /memories/recalls)
	RecallMemories(ctx context.Context, request RecallMemoriesRequestObject) (RecallMemoriesResponseObject, error)
	// DecideMemory API-09 authorized confirm, reject or revoke under expected revision
	// (POST /memories/{factId}/decisions)
	DecideMemory(ctx context.Context, request DecideMemoryRequestObject) (DecideMemoryResponseObject, error)
	// CreateOperation API-02 create a generation, refinement, preview, release or local-check operation
	// (POST /operations)
	CreateOperation(ctx context.Context, request CreateOperationRequestObject) (CreateOperationResponseObject, error)
	// GetOperation API-03 one committed projection of the operation
	// (GET /operations/{operationId})
	GetOperation(ctx context.Context, request GetOperationRequestObject) (GetOperationResponseObject, error)
	// SubmitCommand API-05 submit a tracked control command
	// (POST /operations/{operationId}/commands)
	SubmitCommand(ctx context.Context, request SubmitCommandRequestObject) (SubmitCommandResponseObject, error)
	// GetCommand Query the original tracked command
	// (GET /operations/{operationId}/commands/{commandId})
	GetCommand(ctx context.Context, request GetCommandRequestObject) (GetCommandResponseObject, error)
	// GetPreview The committed preview of a preview_build operation (saved revision, state, exact artifacts)
	// (GET /operations/{operationId}/preview)
	GetPreview(ctx context.Context, request GetPreviewRequestObject) (GetPreviewResponseObject, error)
	// ReadPreviewArtifact The verified bytes of the preview's module or one of its stylesheets
	// (GET /operations/{operationId}/preview/artifacts/{digest})
	ReadPreviewArtifact(ctx context.Context, request ReadPreviewArtifactRequestObject) (ReadPreviewArtifactResponseObject, error)
	// GetRelease The committed release projection of a release operation (exact subject, approval, per-target receipts, activation)
	// (GET /operations/{operationId}/release)
	GetRelease(ctx context.Context, request GetReleaseRequestObject) (GetReleaseResponseObject, error)
	// ReadSource The exact source archive a workbench edits (a generation's certified source or a preview build's edited source)
	// (GET /operations/{operationId}/source)
	ReadSource(ctx context.Context, request ReadSourceRequestObject) (ReadSourceResponseObject, error)
	// CreatePreparation API-01 accept a prompt into a Preparation operation
	// (POST /preparations)
	CreatePreparation(ctx context.Context, request CreatePreparationRequestObject) (CreatePreparationResponseObject, error)
	// SubmitAnswer API-06 submit a clarification answer bound to the current question set revision
	// (POST /preparations/{operationId}/answers)
	SubmitAnswer(ctx context.Context, request SubmitAnswerRequestObject) (SubmitAnswerResponseObject, error)
}

type StrictHandlerFunc func(ctx *gin.Context, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictGinServerOptions struct {
	// RequestErrorHandlerFunc is called when a request cannot be parsed or
	// decoded. It is invoked for JSON bind failures, form parse/bind errors,
	// multipart reader errors, media type parse errors, missing multipart
	// boundaries, and request body read errors. The default returns 400.
	RequestErrorHandlerFunc func(ctx *gin.Context, err error)
	// HandlerErrorFunc is called when the application handler (or any
	// middleware wrapping it) returns a non-nil error. The default returns 500.
	HandlerErrorFunc func(ctx *gin.Context, err error)
	// ResponseErrorHandlerFunc is called when the response object fails to
	// serialize (Visit*Response returns an error) or when the handler returns
	// an unexpected response type. The default returns 500.
	ResponseErrorHandlerFunc func(ctx *gin.Context, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictGinServerOptions{
		RequestErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		},
		HandlerErrorFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
		ResponseErrorHandlerFunc: func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictGinServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusBadRequest, gin.H{"msg": err.Error()})
		}
	}
	if options.HandlerErrorFunc == nil {
		options.HandlerErrorFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(ctx *gin.Context, err error) {
			ctx.JSON(http.StatusInternalServerError, gin.H{"msg": err.Error()})
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictGinServerOptions
}

// BeginTransfer operation middleware
func (sh *strictHandler) BeginTransfer(ctx *gin.Context) {
	var request BeginTransferRequestObject

	var body BeginTransferJSONRequestBody
	if err := ctx.ShouldBindJSON(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(ctx, err)
		return
	}
	request.Body = &body

	handler := func(ctx *gin.Context, request interface{}) (interface{}, error) {
		return sh.ssi.BeginTransfer(ctx, request.(BeginTransferRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "BeginTransfer")
	}

	response, err := handler(ctx, request)

	if err != nil {
		sh.options.HandlerErrorFunc(ctx, err)
	} else if validResponse, ok := response.(BeginTransferResponseObject); ok {
		if err := validResponse.VisitBeginTransferResponse(ctx.Writer); err != nil {
			sh.options.ResponseErrorHandlerFunc(ctx, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(ctx, fmt.Errorf("unexpected response type: %T", response))
	}
}

